_FALLBACK = {w: sum(t.values()) / len(t) for w, t in _W.items()}

# The face a width is measured in follows the same rule `Reel.text` letters by: a style pack
# names a display face for large type and a body face for the rest. The build sets them for its
# own context, so concurrent builds in one process never measure in each other's faces.
_FACES: ContextVar[dict] = ContextVar("launch_reel_faces", default={})
DISPLAY_MIN = 40        # px; from this size up a line is set in the display face
MONO_EM = 0.602         # Menlo / DejaVu Sans Mono advance


def set_faces(display: str = "Inter Brand", body: str = "Inter Brand", display_scale: float = 1.0):
    return _FACES.set({"display": display, "body": body, "scale": display_scale})


def face_for(size: float) -> tuple[str, float]:
    f = _FACES.get()
    if size >= DISPLAY_MIN:
        return f.get("display", "Inter Brand"), f.get("scale", 1.0)
    return f.get("body", "Inter Brand"), 1.0


def text_width(text: str, size: float, weight: int = 600, letter_spacing: float = 0,
               face: str | None = None) -> float:
    """Width in px of one line of `text` at `size`. A weight between the tabled ones snaps to
    the nearest, which is within a percent or two either way. Without `face`, the face is the
    one the current style letters this size in."""
    scale = 1.0
    if face is None:
        face, scale = face_for(size)
    if face == "mono":
        return len(text) * MONO_EM * size + letter_spacing * len(text)
    table = FACES.get(face, _W)
    w = min(table, key=lambda k: abs(k - weight))
    tab = table[w]
    fb = sum(tab.values()) / len(tab)
    return sum(tab.get(c, fb) for c in text) * size * scale + letter_spacing * len(text)
